require(isPauser[msg.sender], "Not a Pauser");
_;
}

modifier notPaused {
require(!paused, "Contract is paused");
_;
}

function pause() external onlyPauser notPaused {
paused = true;
emit Paused();
}

function unpause() external onlyPauser {
